function displayName(e){let t=lastSegment(e).replace(/([a-z0-9])([A-Z])/gu,`$1 $2`).replace(/([A-Z]+)([A-Z][a-z])/gu,`$1 $2`).split(SEPARATORS).filter(e=>e!==``).map(e=>e.length>1&&e===e.toUpperCase()?e:e.toLowerCase());return t.length===0?e:t.join(` `)}function displayTitle(e){return capitalize(displayName(e))}function displayProperName(e){let t=lastSegment(e).split(SEPARATORS).filter(e=>e!==``).join(` `);return t===``?e:capitalize(t)}const SEPARATORS=/[\s_-]+/u;function lastSegment(e){return e.split(`__`).findLast(e=>e!==``)??e}function capitalize(e){return e.charAt(0).toUpperCase()+e.slice(1)}export{displayName,displayProperName,displayTitle};